package com.refind.service.impl;
import com.refind.dao.ItemDAO; import com.refind.exception.ValidationException; import com.refind.model.Item; import com.refind.model.enums.*; import com.refind.service.ItemService; import java.util.*;
public class JdbcItemService implements ItemService { private final ItemDAO dao; public JdbcItemService(ItemDAO dao){this.dao=dao;} private void validate(Item i){if(i==null||i.getTitle()==null||i.getTitle().isBlank())throw new ValidationException("Item title is required.");if(i.getType()==null)throw new ValidationException("Item type is required.");if(i.getCategory()==null||i.getCategory().getId()==null)throw new ValidationException("Category is required.");if(i.getReportedBy()==null||i.getReportedBy().getId()==null)throw new ValidationException("Reporter is required.");if(i.getStatus()==null)i.setStatus(i.getType()==ItemType.LOST?ItemStatus.LOST:ItemStatus.FOUND);} public Item reportItem(Item i){validate(i);return dao.save(i);} public Optional<Item> getItemById(Long id){return dao.findById(id);} public List<Item> getAllItems(){return dao.findAll();} public List<Item> getItemsByType(ItemType t){return dao.findByType(t);} public List<Item> getItemsByCategory(Long id){return dao.findByCategory(id);} public List<Item> getItemsByStatus(ItemStatus s){return dao.findByStatus(s);} public List<Item> getItemsByUser(Long id){return dao.findByUser(id);} public List<Item> searchItems(String k){return dao.search(k);} public Item updateItem(Item i){validate(i);if(i.getId()==null)throw new ValidationException("Item id is required for update.");return dao.update(i);} public boolean deleteItem(Long id){return dao.deleteById(id);} }
